from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..util import wrap_result
from ..validators import IsOneOf, Matches
from ..converter import to_int


class RadParamsInterface(BaseInterface):

    @wrap_result
    def get_bts_rad_parameters(self, type, timeout=120, alias="default"):
        """Get RAD parameters.

        :param integer component: BTS system component number
        :param string type: Requested (SW Config, present in file) or Applied (SW Config + changes made during runtime)
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsOneOf("Requested", "Applied").check(type)

        result = self.store.get(alias).execute_infomodel_request("getRadParameters", {"type": type}, timeout)
        return result[0]["flags"]

    def change_bts_rad_parameters(self, component, params, timeout=300, alias="default"):
        """Change RAD parameters.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        component = to_int(component)
        timeout = timestr_to_secs(timeout)
        Matches(r"(\d+:\d+,?)+").check(params)

        self._change_rad_params("DynamicChanges", component, params, timeout, alias)

    def change_bts_rad_parameters_permanently(self, component, params, timeout=300, alias="default"):
        """Change RAD parameters permanently.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        component = to_int(component)
        timeout = timestr_to_secs(timeout)
        Matches(r"(\d+:\d+,?)+").check(params)

        self._change_rad_params("PersistentChanges", component, params, timeout, alias)

    def change_bts_rad_parameters_with_overreset(self, component, params, timeout=300, alias="default"):
        """Change RAD parameters persistent over one reset.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        component = to_int(component)
        timeout = timestr_to_secs(timeout)
        Matches(r"(\d+:\d+,?)+").check(params)

        self._change_rad_params("PersistentOverOneResetChanges", component, params, timeout, alias)

    def reset_bts_rad_parameters(self, component, params, timeout=300, alias="default"):
        """Reset RAD parameters.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        component = to_int(component)
        timeout = timestr_to_secs(timeout)
        Matches(r"(\d+:\d+,?)+").check(params)

        self._change_rad_params("FactoryDefaults", component, params, timeout, alias)

    def _change_rad_params(self, setting_type, component, params, timeout, alias):
        changed_params = self._parse_rad_parameters(params)
        self.store.get(alias).execute_procedure(
            "setRadParam", {"btsSwSystemComponent": component, "radSettingType": setting_type, "radParams": changed_params}, timeout)

    def _parse_rad_parameters(self, params):
        changed_params = []
        for param in params.split(","):
            if not param:
                continue
            index, value = param.split(":")
            changed_params.append({"paramIndexNumber": int(index), "paramValue": int(value)})
        return changed_params
